css:
.stats__tab {
  position: relative;
  min-height: 58px;
  padding: 0 20px 18px 0;
  border: 0;
  background: transparent;
  color: rgb(247 248 248 / 0.5);
  font: inherit;
  font-size: clamp(14px, 1.22vw, 22px);
  font-weight: 430;
  letter-spacing: 0;
  text-align: left;
  cursor: pointer;
  transition: color 220ms ease;
}
